import crypto from 'node:crypto'

app.post('/webhooks', express.raw({ type: 'application/json' }), async (req, res) => {
  const ts = Number(req.get('Webhook-Timestamp'))
  const sig = Buffer.from(req.get('Webhook-Signature') ?? '', 'hex')
  if (!ts || Math.abs(Date.now() / 1000 - ts) > 300) return res.sendStatus(401)
  const expected = crypto.createHmac('sha256', SECRET)
    .update(`${ts}.`).update(req.body).digest()
  if (sig.length !== expected.length || !crypto.timingSafeEqual(sig, expected)) return res.sendStatus(401)
  const event = JSON.parse(req.body)
  // ... dedupe and enqueue, see next example
  res.sendStatus(200)
})

